# Set working directory
WORKDIR /app

# Copy package.json, package-lock.json and installation dependencies
COPY package*.json./

RUN npm install --silent

EXPOSE 4444 # expose cypress default port

CMD ["npx", "cypress", "run"]
```

4. Run the following commands to create a docker image for cypress:
```bash
mkdir cypress_project
cd cypress_project

yarn init -y
yarn add --dev cypress duplicator
touch Dockerfile

